  hosts: Array<{
    label: string;
    host: string;
    url: string;
    ok: boolean;
    status?: number;
    error?: string;
  }>;
}> {
  const hosts: Array<{
    label: string;
    host: string;
    url: string;
    ok: boolean;
    status?: number;
    error?: string;
  }> = [];

