      logStreamBytes += Buffer.byteLength(payload, "utf8");
      logStream.write(payload);
    } finally {
      logDraining = false;
      reportDropsIfNeeded();
      // If more arrived while we were draining, keep going.
      if (logQueue.length > 0) drainLogs();
