#!/usr/bin/env node
/**
 * Security Test Script
 * 
 * This script tests the security improvements made to the application
 * and verifies the expected security headers are present.
 */

const express = require('express');
const helmet = require('helmet');
const request = require('supertest');

// Import the app
const app = require('./app');

/**
 * Test security headers
 */
async function testSecurityHeaders() {
  console.log('\n=== Testing Security Headers ===\n');

  const response = await request(app).get('/health');

  console.log('Response Headers:');
  console.log('-'.repeat(50));

  const securityHeaders = {
    'content-security-policy': 'Content-Security-Policy',
    'x-frame-options': 'X-Frame-Options',
    'x-content-type-options': 'X-Content-Type-Options',
    'x-xss-protection': 'X-XSS-Protection',
    'cache-control': 'Cache-Control',
    'permissions-policy': 'Permissions-Policy',
    'strict-transport-security': 'Strict-Transport-Security',
  };

  let headerCount = 0;
  for (const [key, name] of Object.entries(securityHeaders)) {
    if (response.headers[key]) {
      console.log(`✓ ${name}: ${response.headers[key].substring(0, 50)}${response.headers[key].length > 50 ? '...' : ''}`);
      headerCount++;
    } else {
      console.log(`❌ ${name}: Missing`);
    }
  }

  console.log(`\nTotal security headers: ${headerCount}/${Object.keys(securityHeaders).length}`);

  return headerCount >= Object.keys(securityHeaders).length * 0.8; // Allow 20% margin
}

/**
 * Test CORS configuration
 */
async function testCORS() {
  console.log('\n=== Testing CORS Configuration ===\n');

  // Test with missing Origin header
  console.log('Test 1: Request without Origin header');
  const response1 = await request(app).get('/health');
  if (!response1.headers['access-control-allow-origin']) {
    console.log('✓ No Access-Control-Allow-Origin header (correct for no origin)');
  } else {
    console.log('❌ Access-Control-Allow-Origin header present (potential security issue)');
  }

  // Test with allowed Origin header
  console.log('\nTest 2: Request with allowed Origin header');
  const response2 = await request(app)
    .get('/health')
    .set('Origin', 'https://example.com');

  if (response2.headers['access-control-allow-origin']) {
    console.log('✓ Access-Control-Allow-Origin header present');
  } else {
    console.log('❌ Access-Control-Allow-Origin header missing (may be expected if not in allowed list)');
  }

  // Test preflight OPTIONS request
  console.log('\nTest 3: OPTIONS preflight request');
  const response3 = await request(app)
    .options('/users')
    .set('Origin', 'https://example.com')
    .set('Access-Control-Request-Method', 'GET');

  if (response3.status === 204 || response3.status === 200) {
    console.log('✓ OPTIONS request handled correctly');
  } else {
    console.log('❌ OPTIONS request failed');
  }

  return true;
}

/**
 * Test input validation
 */
async function testInputValidation() {
  console.log('\n=== Testing Input Validation ===\n');

  // Test ID validation
  console.log('Test 1: Invalid ID in path');
  const response1 = await request(app).get('/users/invalid');
  if (response1.status === 400 || response1.status === 404) {
    console.log('✓ Invalid ID rejected');
  } else {
    console.log('❌ Invalid ID accepted');
  }

  // Test negative ID
  console.log('\nTest 2: Negative ID in path');
  const response2 = await request(app).get('/users/-1');
  if (response2.status === 400) {
    console.log('✓ Negative ID rejected');
  } else {
    console.log('❌ Negative ID accepted (status: ' + response2.status + ')');
  }

  // Test large ID
  console.log('\nTest 3: Large ID in path');
  const response3 = await request(app).get('/users/9999999999');
  if (response3.status === 400) {
    console.log('✓ Large ID rejected');
  } else {
    console.log('❌ Large ID accepted (status: ' + response3.status + ')');
  }

  // Test invalid email in POST
  console.log('\nTest 4: Invalid email in POST request');
  const response4 = await request(app)
    .post('/users')
    .set('Content-Type', 'application/json')
    .send({
      name: 'Test User',
      email: 'invalid-email',
    });

  if (response4.status === 400) {
    console.log('✓ Invalid email rejected');
  } else {
    console.log('❌ Invalid email accepted');
  }

  // Test empty name
  console.log('\nTest 5: Empty name in POST request');
  const response5 = await request(app)
    .post('/users')
    .set('Content-Type', 'application/json')
    .send({
      name: '',
      email: 'test@example.com',
    });

  if (response5.status === 400) {
    console.log('✓ Empty name rejected');
  } else {
    console.log('❌ Empty name accepted');
  }

  return true;
}

/**
 * Test rate limiting
 */
async function testRateLimiting() {
  console.log('\n=== Testing Rate Limiting ===\n');

